entry.command:
python3 -B -c 'import json,subprocess;from pathlib import Path;P=Path;assert P("/sys/block/mmcblk1/device/cid").read_text().strip()=="0353445345333247805558c00401a100";out={"processes":[],"files":{},"command":{}}
for p in P("/proc").iterdir():
 if p.name.isdigit():
  try:
   comm=(p/"comm").read_text().strip()
   if comm in ["Xorg","matchbox-window","matchbox-deskto"]:
    env=dict(x.split("=",1) for x in (p/"environ").read_bytes().decode(errors="replace").split("\0") if "=" in x);out["processes"].append({"pid":p.name,"comm":comm,"argv":(p/"cmdline").read_bytes().decode(errors="replace").split("\0"),"display_env":{k:env[k] for k in ["DISPLAY","XAUTHORITY"] if k in env}})
  except OSError:pass
for p in [P("/var/log/Xorg.0.log"),P("/etc/X11/xorg.conf")]+list(P("/etc/X11/xorg.conf.d").glob("*.conf")):
 if p.is_file():out["files"][str(p)]=p.read_text(errors="replace")
r=subprocess.run(["systemctl","cat","xserver-nodm.service"],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=20);out["command"]={"rc":r.returncode,"stdout":r.stdout,"stderr":r.stderr};print(json.dumps(out,indent=2))'

python3 -B -c 'import json,os,subprocess,shutil;out=[];env=os.environ.copy();env["DISPLAY"]=":0"
for c in [["xrandr","--display",":0","--verbose"],["xset","-display",":0","q"],["modetest","-M","xlnx","-c","-p"]]:
 if not shutil.which(c[0]):out.append({"argv":c,"available":False});continue
 try:
  r=subprocess.run(c,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=25);out.append({"argv":c,"rc":r.returncode,"stdout":r.stdout,"stderr":r.stderr})
 except subprocess.TimeoutExpired:out.append({"argv":c,"error":"timeout"})
print(json.dumps(out,indent=2))'

python3 -B -c 'import json;from pathlib import Path;P=Path;out={}
for p in P("/sys/firmware/devicetree/base").glob("**/display@fd4a0000"):
 for n in ["compatible","status","clock-names","model"]:
  f=p/n
  if f.exists():out[str(f)]=f.read_bytes().decode(errors="replace").replace("\0","|")
p=P("/sys/class/drm/card0-DP-1/edid");out["edid_bytes_after_probe"]=len(p.read_bytes()) if p.exists() else None;print(json.dumps(out,indent=2))'
